class Solution {
public:
    string reorganizeString(string s) {
        int freq[26] = {0};
        for (char c : s) freq[c - 'a']++;

        priority_queue<pair<int,char>> pq;
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) pq.push({freq[i], (char)('a' + i)});
        }

        string result;
        while (pq.size() >= 2) {
            auto [cnt1, ch1] = pq.top(); pq.pop();
            auto [cnt2, ch2] = pq.top(); pq.pop();
            result += ch1;
            result += ch2;
            if (--cnt1 > 0) pq.push({cnt1, ch1});
            if (--cnt2 > 0) pq.push({cnt2, ch2});
        }

        if (!pq.empty()) {
            auto [cnt, ch] = pq.top();
            if (cnt > 1) return "";
            result += ch;
        }

        return result;
    }
};
